    )

def _state_for_tool(name: str) -> dict:
    return {
        "messages": [
            AIMessage(
                content="",
                tool_calls=[
                    {
                        "id": "call_1",
                        "name": name,
                        "args": {"query": "keyword_score"},
                    }
                ],
            )
        ],
        "stop_reason": "running",
        "tool_call_count": 0,
        "max_tool_calls": 10,
        "max_identical_tool_calls": 2,
    }

def test_no_tool_calls_routes_to_finalize() -> None:
    nodes = HumanReviewToolAgentNodes(dependencies=_dependencies())
    command = nodes.controller_node(
        {
            "messages": [AIMessage(content="answer")],
            "stop_reason": "running",
        }
    )

    assert command.goto == "finalize"

def test_hitl_disabled_routes_to_prepare_tools() -> None:
    nodes = HumanReviewToolAgentNodes(
        dependencies=_dependencies(enable_human_review=False)
    )
    command = nodes.controller_node(_state_for_tool("read_file_range"))

    assert command.goto == "prepare_tools"

def test_run_project_tests_rejects_absolute_path(
    tmp_path,
) -> None:
    registry = build_code_doc_tool_registry(
        project_root=str(tmp_path),
    )
    executor = ToolExecutor(registry)

    result = executor.execute(
        tool_name="run_project_tests",
        arguments={
            "test_path": str(tmp_path / "tests"),
            "max_seconds": 10,
        },
    )

    assert result.success is False
    assert result.error_code == "ABSOLUTE_PATH_FORBIDDEN"

def test_run_project_tests_rejects_path_outside_project(
    tmp_path,
) -> None:
    outside = tmp_path.parent / "outside_tests"
    outside.mkdir(exist_ok=True)

    registry = build_code_doc_tool_registry(
        project_root=str(tmp_path),
    )
    executor = ToolExecutor(registry)

    result = executor.execute(
        tool_name="run_project_tests",
        arguments={
            "test_path": "../outside_tests",
            "max_seconds": 10,
        },
    )

    assert result.success is False
    assert result.error_code == "PATH_OUTSIDE_PROJECT"

def success_response(data: Any = None) -> Dict[str, Any]:
    """
    构造统一成功响应。
    """
    return {
        "success": True,
        "data": data,
    }

def error_response(
    code: str,
    message: str,
    details: Optional[Any] = None,
) -> Dict[str, Any]:
    """
    构造统一失败响应。
    """
    error = {
        "code": code,
        "message": message,
    }

    if details is not None:
        error["details"] = details

    return {
        "success": False,
        "error": error,
    }

def http_status_to_error_code(status_code: int) -> str:
    """
    将 HTTP 状态码转换为统一错误码。
    """
    if status_code == 400:
        return "BAD_REQUEST"

    if status_code == 404:
        return "NOT_FOUND"

    if status_code == 422:
        return "VALIDATION_ERROR"

    if status_code == 500:
        return "INTERNAL_SERVER_ERROR"
    if status_code == 502:
        return "MODEL_SERVICE_ERROR"

    if status_code == 504:
        return "MODEL_SERVICE_TIMEOUT"
    return "HTTP_ERROR"

def get_checkpoint_runtime(request: Request) -> SQLiteCheckpointRuntime:
    runtime = getattr(request.app.state, "checkpoint_runtime", None)

    if runtime is None:
