def tokenize(
    self,
    text: str,
) -> List[str]:
    """
    Mock Provider 使用的简单分词器。
    """
    return re.findall(
        r"[a-zA-Z0-9_]+|[\u4e00-\u9fff]",
        text.lower(),
    )

def normalize(
    self,
    vector: List[float],
) -> List[float]:
    """
    对向量做 L2 归一化，让余弦相似度计算更稳定。
    """
    norm = math.sqrt(
        sum(value * value for value in vector)
    )

    if norm == 0:
        return vector

    return [
        value / norm
        for value in vector
    ]

