    value: tuple[str, ...],
) -> tuple[str, ...]:
    normalized: list[str] = []

    for tool_name in value:
        name = tool_name.strip()

        if not name:
            raise ValueError(
                "approval_required_tools 不能包含空工具名"
            )

        if name not in normalized:
            normalized.append(name)

    return tuple(normalized)

